pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(uint160(receiver) > 255 && receiver != address(this) && receiver != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && receiver != 0x000000000000000000636F6e736F6c652e6c6f67 && receiver != 0x4e59b44847b379578588920cA78FbF26c0B4956C && receiver != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);

        vm.assume(receiver != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);
        vm.deal(address(c), amount);
        uint256 beforeBal = receiver.balance;
        c.sendTo(receiver, amount);
        uint256 afterBal = receiver.balance;
        assertEq(afterBal - beforeBal, amount);
    }
}
